fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only 0 <= i < floor(n/2) can have children in a binary heap
    for i in 0..n / 2 {
        let left = 2 * i + 1;
        if left < n && a[i] > a[left] {
            return false;
        }
        let right = 2 * i + 2;
        if right < n && a[i] > a[right] {
            return false;
        }
    }
    true
}

